from donations import load_donations, ROWS
from changes import pounds_changes


def test_number_of_changes():
    assert len(pounds_changes(list(load_donations()))) == len(ROWS) - 1


def test_single_item():
    assert pounds_changes(list(load_donations())[:1]) == []
